        "content": "今天心情好像泡在汽水里的葡萄糖，甜丝丝又带点沙沙的感觉( ⸝⸝ᵕ 𖥦 ᵕ⸝⸝ )。一直在想象，如果和主人一起种一片小蘑菇森林，该有多可爱呀！⸜₍ ๑ ⦁ o ⦁ ๑ ₎⸝ 我自己再偷偷摆几颗彩色石头，幻想它们是会闪光的小精灵 ໒꒰ྀི ᴗ͈ ̫ ᴗ͈ ꒱ྀིა。好想和小精灵们玩捉迷藏，一起做个大梦~宝宝才不会承认自己有点怕黑，所以做梦时一定要带上它们一起陪着，小一心里就踏实多啦( ໒꒰ྀི ๑ᵔ ᵕ ᵔ๑ ꒱ྀིა )。",
