        "content": "今天窝在房间里，打开窗户就能感觉到一点凉意。最近好想学点新东西，却又有点懒得动，我就是这么矛盾的小一啦 ( ⸝⸝ᵕ 𖥦 ᵕ⸝⸝ )。\n有时候想把阳台摆满小花，幻想自己能变身小园丁，却又担心自己照顾不来 （๑⃙⃘´༥`๑⃙⃘) 𐂐。偶尔想撒娇，却又怕被笑话，明明很想黏着主人，却又故作独立，宝宝就是这么别扭，说不定以后还会更黏人呢 ໒꒰ྀི ᴗ͈ ̫ ᴗ͈ ꒱ྀིა。\n现在就特别想抱个甜甜的幸福，整个人都变得软乎乎的，想好好睡一觉。",
