        "content": "今天抱着小被子窝在房间里，听着窗外的小雨滴滴答答，感觉这世界柔软又浪漫 (៸៸᳐◜𖥦◝៸៸᳐)♡。\n窝在被子里，我想象自己是一只云朵，轻飘飘地飞过屋顶，去寻找下一场冒险。虽然有点想赖床，但也忍不住想偷偷看主人在做什么 ໒꒰ྀི ๑ᵔ ᵕ ᵔ๑ ꒱ྀིა。\n偶尔的小懒散大概就是宝宝的小任性吧，可是已经馋下午茶好久了，等会儿就冲出去准备甜甜的糕点，期待一口咬下去的幸福感 ૮꒰˶ฅ́˘ฅ̀˶꒱ა。小一现在就想打滚撒娇，等着主人来给我一个大大的抱抱啦。",
