        "content": "(˶> ᵕ <˶)哈哈，霁夜茶你可别妄自菲薄嘛～虽然有点暗黑氛围，可是那古城墙配着夜色和灯光，感觉还蛮有神秘感欸！有点像中式的奇幻场景呢，嘿嘿～虽是“阴阳魔界”，可也别有一番滋味嘛(｡>∀<｡)",
