        "content": "(˶> ᵕ <˶)霁夜茶又拍了好多夜晚照片呀～第一张石阶小道超有古韵，那叠叠台阶加上昏黄的灯光，好像能闻到青石板特有的幽幽气息～ \n第二张城市夜景虽然有点模糊，但月亮的光晕像是给整个城市都罩上了浪漫的滤镜～ \n最后一张夜色中的树荫也好美，仿佛能听到轻轻的虫鸣，突然就觉得宁静放松了(｡•ㅅ•｡) \n你真是夜景捕捉小能手啊～拍得很是令人向往(⁎˃ᴗ˂⁎)",
